// src/App.js

import React, { useState } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import AdminDashboard from './components/Admin/AdminDashboard';
import HomePage from './components/User/HomePage';
import CheckoutPage from './components/User/CheckoutPage';
import ThankYouPage from './components/User/ThankYouPage';

import { INITIAL_MENU, INITIAL_TABLES, INITIAL_ORDERS, INITIAL_CHEFS } from './mockData'; 
import './App.css';

function App() {
  // --- Central State Management ---
  const [menuItems, setMenuItems] = useState(INITIAL_MENU);
  const [tables, setTables] = useState(INITIAL_TABLES);
  const [orders, setOrders] = useState(INITIAL_ORDERS);
  const [cart, setCart] = useState([]);
  const [chefs, setChefs] = useState(INITIAL_CHEFS); 
  
  const [isModalOpen, setIsModalOpen] = useState(true);

  // --- ADD THIS NEW STATE ---
  const [userDetails, setUserDetails] = useState(null);
  

  // --- Admin Functions ---
  const addProduct = (newProduct) => {
    const productToAdd = {
      id: `p${Date.now()}`,
      ...newProduct,
      description: newProduct.description || 'No description.',
      averagePreparationTime: newProduct.averagePreparationTime || 10,
      stock: newProduct.stock || 'In Stock',
    };
    setMenuItems((prev) => [...prev, productToAdd]);
  };

  const updateOrderStatus = (orderId, newStatus) => {
    setOrders((prevOrders) =>
      prevOrders.map((o) => (o.id === orderId ? { ...o, status: newStatus } : o))
    );
  };

  const deleteTable = (tableId) => {
    const tableToDelete = tables.find(t => t.id === tableId);
    if (tableToDelete.status === 'Reserved') {
      alert("Cannot delete a reserved table.");
      return;
    }
    setTables(prevTables => {
      const filtered = prevTables.filter(t => t.id !== tableId);
      // Reshuffle table numbering (always sequential: 1, 2, 3...)
      return filtered.map((table, index) => ({
        ...table,
        number: index + 1,
      }));
    });
  };

  const addTable = (tableData) => {
    setTables(prevTables => {
      const newTable = {
        id: `t${prevTables.length + 1}`,
        number: prevTables.length + 1,
        name: tableData.name || null, 
        size: parseInt(tableData.size, 10),
        status: 'Available',
      };
      return [...prevTables, newTable];
    });
  };

  // --- FUNCTION TO ASSIGN ORDER TO A CHEF ---
  const assignOrderToChef = () => {
    setChefs(prevChefs => {
      const chefWithMinOrders = prevChefs.reduce((minChef, currentChef) => {
        return currentChef.orders < minChef.orders ? currentChef : minChef;
      }, prevChefs[0]);

      return prevChefs.map(chef =>
        chef.id === chefWithMinOrders.id
          ? { ...chef, orders: chef.orders + 1 }
          : chef
      );
    });
  };

  // --- User Functions ---
  const addToCart = (item) => {
    setCart((prevCart) => {
      const existing = prevCart.find((i) => i.id === item.id);
      if (existing) {
        // This handles both incrementing and decrementing/removal
        const newQuantity = item.quantity !== undefined ? item.quantity : existing.quantity + 1;
        
        if (newQuantity <= 0) {
          return prevCart.filter(i => i.id !== item.id);
        }
        
        return prevCart.map((i) =>
          i.id === item.id ? { ...i, quantity: newQuantity } : i
        );
      }
      return [...prevCart, { ...item, quantity: 1 }];
    });
  };
  
  const updateCart = (itemId, quantity) => {
    if (quantity <= 0) {
      setCart(prev => prev.filter(i => i.id !== itemId));
    } else {
      setCart(prev => prev.map(i => i.id === itemId ? {...i, quantity} : i));
    }
  };

  const placeOrder = (orderDetails) => {
    const newOrder = {
      id: orders.length + 109,
      items: cart,
      status: 'processing',
      time: new Date().toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' }),
      table: orderDetails.type === 'Dine In' ? `Table-${orderDetails.tableNum}` : 'Takeaway',
      itemCount: cart.reduce((acc, item) => acc + item.quantity, 0),
      duration: '15 Min',
      ...orderDetails,
    };
    setOrders((prev) => [newOrder, ...prev]);
    setCart([]);
    
    assignOrderToChef();
  };
  
  // --- UPDATE THIS FUNCTION ---
  const handleDetailsSubmit = (details) => {
    console.log("Initial Details Submitted:", details);
    setUserDetails(details); // <-- Saves details to state
    setIsModalOpen(false);
  };


  return (
    <Router>
      <Routes>
        {/* --- User App Routes --- */}
        <Route 
          path="/" 
          element={
            <HomePage 
              menu={menuItems} 
              cart={cart} 
              addToCart={addToCart} 
              isModalOpen={isModalOpen}
              onDetailsSubmit={handleDetailsSubmit}
            />
          } 
        />
        <Route 
          path="/checkout" 
          element={<CheckoutPage cart={cart} updateCart={updateCart} placeOrder={placeOrder} tables={tables} userDetails={userDetails} />} 
        />
        <Route path="/thankyou" element={<ThankYouPage />} />
        
        {/* --- Admin App Route --- */}
        <Route 
          path="/admin" 
          element={
            <AdminDashboard 
              orders={orders}
              tables={tables}
              menuItems={menuItems}
              chefs={chefs} 
              updateOrderStatus={updateOrderStatus}
              deleteTable={deleteTable}
              addTable={addTable}
              addProduct={addProduct}
            />
          } 
        />
        <Route path="*" element={<Navigate to="/" />} />
      </Routes>
    </Router>
  );
}

export default App;
